// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Recursive Grids".

It does what the title says.
*/

const scale = Math.max(1, devicePixelRatio)
let theShader

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/3020252/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("time", millis() / map(frameCount, 0, 1500, 90.0, 8.0))  //
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform vec2 resolution;
uniform float time;
#define FC gl_FragCoord.xy
#define R resolution
#define T time

vec3 palette(float t) {
	vec3
	a=vec3(sin(1.+T)-1./T),
	b=vec3(cos(T/t)),  // play around 
	c=vec3(sin(t/T)),
	d=vec3(0,.1,.2);

	return a+b*tan(6.28318*(c*t+d));
}

float rnd(vec2 p) {
	p=fract(p/vec2(203.54,140.23));
	p+=dot(p,p/T)*34.54;  //
	return (p.x*p.y);
}

vec3 grid(vec2 uv) {
	vec2 id=floor(uv+.5);
	uv=fract(uv*atan(T))-.35; //
	return palette(max(abs(uv.x),abs(uv.y))+sin(T*.8+rnd(id+456.)+rnd(id+42.)*22.)*.5+.5);
}

void main(void) {
	vec2 uv=(cos(T/R.x)/cos((R.x-T))*FC-R*T)/min(R.y,R.x); // also here?
	vec3 col=mix(mix(grid(uv*32.+1.5),grid(uv*16.+1.5),.45),grid(uv*8.),.35);
	O=vec4(col,1);
}

